cat > /workspace/scratch/dc_gen.awk <<'EOF'
# usage: awk -v ALPHA="a,:,/,?,#" -v LEN=7 -f dc_gen.awk
BEGIN{
  n=split(ALPHA,A,",");
  total=1; for(i=0;i<LEN;i++) total*=n;
  for(x=0;x<total;x++){
    v=x; s="";
    for(i=0;i<LEN;i++){ s = A[(v%n)+1] s; v=int(v/n); }
    print s;
  }
}
EOF
cd /workspace/scratch && awk -v ALPHA="a,:,/,?,#" -v LEN=3 -f dc_gen.awk | wc -l && awk -v ALPHA="a,:,/,?,#" -v LEN=2 -f dc_gen.awk | tr '\n' ' '

cd /workspace/scratch && awk 'BEGIN{
  n=split("a,b,8,:,/,?,#,@,.,-,+,%,[,],~SP~",A,",");
  A[15]=" ";
  srand(20260808);
  for(c=0;c<80000;c++){
    L=7+int(rand()*14);  # 7..20
    s="";
    for(i=0;i<L;i++) s=s A[1+int(rand()*n)];
    print s;
  }
}' > dc_rand_wide.txt; wc -l dc_rand_wide.txt; head -6 dc_rand_wide.txt; awk '{print length($0)}' dc_rand_wide.txt | sort -n | uniq -c | tr '\n' ' '

cd /workspace/scratch && awk 'BEGIN{
 D[1]=":"; D[2]="/"; D[3]="?"; D[4]="#"; D[5]="@";
 nd=5;
 # repeated single delimiters, 1..24
 for(d=1;d<=nd;d++){ s=""; for(k=1;k<=24;k++){ s=s D[d]; print s; print "a" s; print s "a"; print "a" s "a"; print "http" s "x"; } }
 # repeated pairs / triples of delimiter groups
 nG=split("://,://:,:///,//,///,////,?#,#?,?#?#,@@,@@@,:@,@:,/@,@/,:/,/:,?/,/?,#/,/#,:?,?:,:#,#:,?@,@?,#@,@#,://@,@://,://:,:/:/,a:,:a,8:,:8,%,%%,[,],[],[::],..,.",G,",");
 for(g=1;g<=nG;g++){ s=""; for(k=1;k<=8;k++){ s=s G[g]; print s; print "http" s; print s "host"; print "http" s "host"; print "a" s "b" s "c"; } }
 # scheme + pile of delimiters + tail
 nT=split("://,:,//,///,://///,@,?,#",T,",");
 nP=split("a,ab,8,80,a8,,.,-,~,[a],a.b,1.2.3.4",P,",");
 for(t=1;t<=nT;t++) for(p=1;p<=nP;p++) for(q=1;q<=nP;q++){
   print "http" T[t] P[p] ":" P[q];
   print "http" T[t] P[p] "@" P[q];
   print "http" T[t] P[p] "/" P[q];
   print "http" T[t] P[p] "?" P[q];
   print "http" T[t] P[p] "#" P[q];
   print "http" T[t] P[p] ":" P[q] "/x?y#z";
 }
}' > dc_patho.txt; sort -u dc_patho.txt > dc_patho_u.txt; wc -l dc_patho.txt dc_patho_u.txt; bash dc_run.sh dc_patho_u.txt
